INSERT INTO `quest_request_items` (`ID`,`EmoteOnComplete`,`EmoteOnIncomplete`,`CompletionText`,`VerifiedBuild`) VALUES
(26921,0,0,'Thin out the Scourge forces, $N.  Our victory depends on keeping their numbers down.',0),
(26922,0,0,'I know what those devices sound like when they''ve blown up... and I haven''t heard that sound yet.  Get back out there, $N.',0),
(26923,0,0,'How long must I wait before you''ve done my bidding, $r?',0),
(26924,0,0,'I will not rest until the Lich King''s taint is lifted from Andorhal.',0),
(26930,0,0,'Have you seen the camp yet, $N?',0),
(26931,0,0,'The Dark Lady will not tolerate the living.',0),
(26933,0,0,'For a bunch of combat-trained goons, they certainly have made some progress on that farm.',0),
(26937,0,0,'Have you lost your way, $N?',0),
(26953,0,0,'Zen''Kiki needs a... a big $gbrother:sister;, like you, to help him gain some confidence.',0),
(26954,0,0,'Back so soon?',0),
(26955,0,0,'By the grace of the Earthmother, I hope this works.',0),
(26956,0,0,'Have you finished killing... er, removing those plants yet?',0),
(26978,0,1,'I see you''re still carrying some of those drums with you, $N.  Don''t return until they''ve all been placed.',0),
(27000,0,1,'The spiders tend to be a little skittish.  One of the mustangs should be enough to scare them away.',0),
(27001,0,1,'I don''t need you to kill the spiders... that''s what these soldiers are for.  Think of it as killing two birds with one stone: we''re getting rid of the spiders, and the recruits are getting valuable combat experience.',0),
(27013,0,0,'I have a family to raise, and I need to do whatever I can to protect them.',0),
(27017,0,0,'I wouldn''t expect you to indulge the whims of a nostalgic old man, $N.  Still, if you find yourself in the area...',0),
(27055,0,0,'How is your investigation proceeding, $N?',0),
(27084,0,0,'Deal with these farmers now, $c.  That is your primary objective.  Teach them how truly unprepared they were for the horrors of war.',0),
(27085,0,0,'Dark Lady watch over you.',0),
(27086,0,0,'You will find them to the west, $N.  Do not fail me.',0),
(27117,0,0,'I will not rest until the Lich King''s taint is lifted from Andorhal.',0),
(27151,0,0,'Welcome back.',0),
(27156,0,0,'I''m not paying you to talk to me.  I''m paying you to talk with my soldiers... and then fight with them.',0),
(27157,0,0,'I need to get those drudges back to work.',0),
(27159,0,0,'Thin out the Scourge forces, $N.  Our victory depends on keeping their numbers down.',0),
(27160,0,0,'Yes?',0),
(27161,0,0,'I know what those devices sound like when they''ve blown up... and I haven''t heard that sound yet.  Get back out there, $N.',0),
(27162,0,0,'I will not rest until the Lich King''s taint is lifted from Andorhal.',0),
(27163,0,0,'I will not rest until the Lich King''s taint is lifted from Andorhal.',0),
(27164,0,0,'Araj is a formidable opponent.  Be prepared.',0),
(27166,0,0,'It''s good to see you back, $N.',0),
(27167,0,0,'We''ve traveled a long way.  Anything you can spare would be appreciated.',0),
(27168,0,0,'Thank you in advance for your assistance, $c.',0),
(27169,0,0,'Uther was a great hero.  It is my honor to serve him, even after he has passed.',0),
(27171,0,0,'What happened at Uther''s Tomb, $N?',0),
(27172,0,0,'Did Valorfist send you?  He doesn''t know when to let up, does he?',0),
(27173,0,0,'My men need your help, $N.',0),
(27174,0,0,'If we''re going to help out in this battle for Andorhal, we need to learn how to fight.',0),
(27198,0,0,'For the Alliance!',0),
(27199,0,0,'You will find them to the east, $N.  Do not fail me.',0),
(27201,0,0,'Koltira, what have you done...',0),
(27202,0,0,'Try not to remember - while they used to be allies, these men are Forsaken now.',0),
(27204,0,0,'How did I let the battle slip between my fingers?',0);
INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild`) VALUES
(26920,396,0,0,0,0,0,0,0,'It''s about time you arrived, $c.',0),
(26921,1,0,0,0,0,0,0,0,'You may not act quickly, but at least you do not fail me.$b$bVery well.  I will have a more important task for you, $N, when the time is right.',0),
(26922,1,1,0,0,0,0,0,0,'These grenades are all explosives, nothing more.  Even as a member of the Royal Apothecary Society, I recognize that some problems are not solved by throwing more plague at them.',0),
(26923,396,0,0,0,0,0,0,0,'With the behemoths out of the way, our victory against the Scourge is inevitable.$b$bOur current chances against the Alliance aren''t quite as favorable... but that''s no concern of yours.  Not yet, anyhow.',0),
(26924,396,0,0,0,0,0,0,0,'Excellently done, $N.  And now, with the leader of the Scourge forces eliminated from Andorhal, we bide our time.',0),
(26925,0,0,0,0,0,0,0,0,'Araj dead... this is good.  The Royal Apothecary Society has done its part.  As have you, $N.',0),
(26926,0,0,0,0,0,0,0,0,'Word arrived shortly before you did, $N.  With the Scourge ejected from Andorhal, the Forsaken has cemented its foothold in Lordaeron.',0),
(26930,6,1,0,0,0,0,0,0,'Burning bodies?  No survivors?  I guessed correctly.$b$bAll the better!  We''re better off without the Scarlet taint upon Lordaeron.  They epitomized all the worst things about humans.',0),
(26931,1,0,0,0,0,0,0,0,'It''s a relief to have those hunters out of the way.  We''re not done killing Alliance, however...',0),
(26933,4,0,0,0,0,0,0,0,'Ha ha!  I hope that they come back as zombies.',0),
(26934,1,0,0,0,0,0,0,0,'Glorious!  This is the last bit I need.$b$bActually, stick around, $n.  Let me tell you a little bit more about our plan.',0),
(26935,2,0,0,0,0,0,0,0,'Welcome to Northridge, $c.',0),
(26936,1,22,22,0,0,0,0,0,'Felstone is cleared and the bombs are set.  I hope you''re ready.  I recommend covering your ears.$b$b<Derrington looks down and places his finger on an ignition switch.>$b$bEVERYBODY, PREPARE FOR IGNITION!  IN 3...$b$b2....$b$b1...',0),
(26937,1,0,0,0,0,0,0,0,'I am able to communicate with you through the Val''kyr, $N.  You have done well.$b$bRemain on Felstone Field.  We must now teach these newly-converted Forsaken how to fight.',0),
(26938,1,1,0,0,0,0,0,0,'When Koltira gives his word, I will bring these val''kyr into Andorhal.  We will win.  And yet another piece of Lordaeron will fall to the might of the Forsaken.',0),
(26952,1,0,0,0,0,0,0,0,'Welcome, $c.  As you can see, our camp is a joint expedition between Argent Crusade members and Cenarion Circle druids, but we welcome all who wish to help heal the land.',0),
(26953,0,0,0,0,0,0,0,0,'It looks like Zen''Kiki is still having a little bit of trouble with his shapeshifting.',0),
(26954,1,6,1,0,0,0,0,0,'Now we''re getting somewhere.  How many birds did Zen''Kiki end up killing?$b$bNone?  You killed them all yourself?$b$bAlright, I suppose we''ll have to find another use for him then.  I will let you know when the time is right.',0),
(26955,1,1,2,0,0,0,0,0,'By the grace of the Earthmother, he''s done it!  Thank you, $N!$b$bI admit, I had nearly given up hope on Zen''Kiki.  It is only due to your patience and diligence that he has come into his own as a druid and member of the Cenarion Circle.  And that''s without even mentioning the good you''ve done for nature.$b$bYou have my admiration and respect.',0),
(26956,2,0,0,0,0,0,0,0,'Thank you for your help, $N.  I know that picking vegetables isn''t the most heroic task imaginable, but even the humblest tasks have their rewards.',0),
(26957,1,274,0,0,0,0,0,0,'It would appear that I arrived before you, $N.$b$bField Agent Kaartish gave me the details about my old home.  It seems my battles with the Scourge aren''t quite over yet.',0),
(26978,4,6,22,22,0,0,0,0,'<Dithers practically glimmers with excitement.>$b$bThe drums are placed?  In their positions?$b$bVery well then, I will give the word to the High Executor.  When the time is ready, he will be the one to press the ignition switch.',0),
(26979,2,0,0,0,0,0,0,0,'$N.  The Dark Lady watches over you.',0),
(26999,2,1,0,0,0,0,0,0,'This will be more than enough, $N.  Now, I will need some time to perform my studies.',0),
(27000,1,1,0,0,0,0,0,0,'Well, it sounds like they''re certainly afraid of the mustang, but they''re not leaving for good.  I can''t have you running around on a horse forever.  Nor do I think you''d want to.$b$bFine.  Bloodshed it is.',0),
(27001,4,1,0,0,0,0,0,0,'That''s much more like it!  Now my lumberjacks can get to work again.$b$bNice riding out there, $N.  You cut a pretty impressive silhouette on that mustang.',0),
(27002,0,0,0,0,0,0,0,0,'$N.  It is truly a pleasure.$b$bI know you are young, and still training, but I''ve had my eye on you.  We among the Argent Crusade are always looking for promising new recruits, and you have indeed shown great promise.  I have no immediate tasks for you, but merely wished to meet you in person, and see for myself what type of $r you really were.$b$bFor the time being, the amenities of Hearthglen are yours to enjoy.  I look forward to our next meeting, $N.  You are dismissed.',0),
(27011,396,6,0,0,0,0,0,0,'I''ll just put this back over in the lumber stores outside.  Nathaniel probably won''t even notice it was missing.',0),
(27012,1,1,0,0,0,0,0,0,'Thank you, $N.  I''ll be throwing these in the fire.  We don''t want those gnolls just sneaking in and stealing them back.',0),
(27013,2,0,0,0,0,0,0,0,'I feel a bit more relieved, $N.  Thank you.',0),
(27017,0,0,0,0,0,0,0,0,'This... Gloria used to read from this prayer book every night!  How had I forgotten?  She was so devout, $N.$b$b<Del''s eyes turn to the finger painting.>$b$bOh...$b$bThis painting... my daughter, Andrea... she loved to... to paint...',0),
(27053,0,0,0,0,0,0,0,0,'Cauldron Lord Soulwrath''s key disintegrates as it touches the lock on the access panel at the base of the cauldron''s platform.  A slight clanking noise is heard within, and the access panel swings open to reveal more viscous toxins within the cauldron''s framework.$B$BThere is a small spigot that the bottle fits well enough under, allowing you to draw a sample for Field Agent Kaartish back at the Menders'' Stead.',0),
(27054,1,0,0,0,0,0,0,0,'The orders in Malicia''s possession incriminate Darkmaster Gandling of the Scholomance, but they also conceal another important bit of information.',0),
(27055,2,1,4,0,0,0,0,0,'You have gone above and beyond, $N.  Not only have we set back the Cult of the Damned in their crusade to re-plague the plaguelands, but you have uncovered another set of dire plans: they continue to re-animate the dead!$b$bYour name will definitely be mentioned when this information is presented to Highlord Fordring, $N.  You have my thanks, and the blessing of the Argent Crusade.',0),
(27057,1,1,0,0,0,0,0,0,'Good work.  One moment please...$b$b<The draenei takes a moment to compare your sample with a sample he presumably had distilled earlier.>$b$bYes, this appears to be the same corruption that is affecting the wildlife.  With this knowledge, and with your combat expertise, we may have the power to stop this.',0),
(27083,396,0,0,0,0,0,0,0,'Thassarian and the humans made their move.  I thought I had an agreement with Thassarian... but I suppose this will do.',0),
(27084,396,396,0,0,0,0,0,0,'Merely a dent in their numbers... but the sight of their fellow men falling from the skies surely weakened their resolve.',0),
(27085,1,0,0,0,0,0,0,0,'You fight well, $N.  I wish I had your ability... and your bravery.',0),
(27086,1,0,0,0,0,0,0,0,'Well done.  With them out of the way, I have no more excuses.$b$bSoon, I must battle Thassarian, for honor and for Andorhal.',0),
(27087,274,1,0,0,0,0,0,0,'You won''t be taking me anywhere, $N.$b$bWhile Koltira prances about with his playmate, Thassarian, I plan to win this battle.  Then I''ll make Koltira suffer for his weakness.$b$bDon''t believe me?  Fine, I''ll let you in on a little secret...',0),
(27089,0,0,0,0,0,0,0,0,'This is the body of Lurid, Thassarian''s trusted knight.  With Thassarian nowhere to be found, it would seem that the Alliance forces have withdrawn.$b$bThe Forsaken have won the battle for Andorhal.',0),
(27090,1,0,0,0,0,0,0,0,'See?  All it took was a little help from the val''kyr.  These creatures are turning to be much more helpful than I had first thought.$b$bNow, on to other matters.',0),
(27117,396,0,0,0,0,0,0,0,'Excellently done, $N.',0),
(27144,274,1,1,0,0,0,0,0,'I have nothing against the Knights of the Ebon Blade, but Koltira needs to be reminded who he works for now.  His loyalty must lie with the Horde.$b$bOr, more specifically, the Forsaken.$b$bI wouldn''t plan on seeing Koltira anytime soon.  Now that I have him... you can rest assured that any bonds he may have had with that Alliance scum will be thoroughly broken.',0),
(27151,1,0,0,0,0,0,0,0,'I must admit, $N... I have been using my mind vision spell to keep tabs on you.  And I must say... the number of gnolls you found on the trail is truly staggering!',0),
(27152,1,0,0,0,0,0,0,0,'Gnolls and necromancy... what a surprise!  And I thought that, here in the Western Plaguelands, we had put these dark days behind us.$b$b<You sense Daria''s eyes focusing on something on the ground.>$b$bWait... what is THAT?',0),
(27153,1,0,0,0,0,0,0,0,'Did you notice, $N?  Many names were mentioned, but one name was mentioned far more than the others.$b$bBisp.',0),
(27154,0,0,0,0,0,0,0,0,'I suppose that we can take his aggression as an admission of guilt.  You alright, $N?',0),
(27155,0,0,0,0,0,0,0,0,'I''m already aware of your actions, $N.  I welcome you into my town, give you my blessing, and what do you do?$b$bYou slay the traitor that we''ve been hunting down for weeks.  Well done.  Your heroism is budding much earlier than even I had anticipated.',0),
(27156,1,24,1,0,0,0,0,0,'I''m just looking over my paperwork here, and it says that we were expecting a $g FEMALE: MALE; $r $c.  You''re not, umm...$b$b<Lieutenant Myner looks at you awkwardly.>$b$bNever mind.  It would appear that you are not the person that I originally hired, but you did a good job.  So I''m going to pay you anyhow.',0),
(27157,4,0,0,0,0,0,0,0,'Nice work!  In retrospect, I''m glad that other $r $c never showed up... you''ve proven to be all the help I need.',0),
(27159,1,0,0,0,0,0,0,0,'You may not act quickly, but at least you do not fail me.$b$bVery well.  I will have a more important task for you, $N, when the time is right.',0),
(27160,396,0,0,0,0,0,0,0,'Abominations... strong.$b$b$N... stronger.',0),
(27161,1,1,0,0,0,0,0,0,'These grenades are all explosives, nothing more.  I may not be a goblin engineer... but I still understand the value of being able to just explode things every once in a while.',0),
(27162,396,0,0,0,0,0,0,0,'Excellently done, $N.  And now, with the leader of the Scourge forces eliminated from Andorhal, we bide our time.',0),
(27163,396,0,0,0,0,0,0,0,'Excellently done, $N.',0),
(27164,396,0,0,0,0,0,0,0,'Araj dead... this is good.  That gnome has done his part in winning this war.  As have you, $N.',0),
(27165,0,0,0,0,0,0,0,0,'Word arrived shortly before you did, $N.  With the Scourge ejected from Andorhal, we are one step closer to retaking Lordaeron.',0),
(27166,0,0,0,0,0,0,0,0,'I will have my fletchers get to work on these.$b$bI''m glad to see you being so useful right away, $N.  Perhaps later I will have some more exciting tasks for you.',0),
(27167,0,0,0,0,0,0,0,0,'You hunt like a true $c.  Even if we can''t set up our homesteads... at least we can still eat.',0),
(27168,2,0,0,0,0,0,0,0,'Hopefully most of them passed on peacefully.  I thank you, $N.',0),
(27169,1,0,0,0,0,0,0,0,'You and the humans at Chillwind Camp wish to re-take Andorhal?  I wish you luck.',0),
(27170,0,0,0,0,0,0,0,0,'Scattered all over the bottom level of the crypt, you find shattered crates that once held weapons and armor.$b$bIt appears that somebody got here before you did.',0),
(27171,274,396,0,0,0,0,0,0,'Attacked by ghosts?  Strange.  I suppose that crypt wasn''t fully healed after all.$b$bYou just missed Thurman Grant... you remember, that oaf of a farmer that was here earlier.  He took his men with him and traveled to the nearest farm... against my orders.',0),
(27172,1,0,0,0,0,0,0,0,'Well, now that you''re here, we''ll gladly take that armor off your hands.$b$bYou can keep the weapons, though.  These men wouldn''t know which end to hold.',0),
(27173,1,273,0,0,0,0,0,0,'You fight well, $r.  My men could stand to learn a few moves from an experienced $c like you.',0),
(27174,1,1,0,0,0,0,0,0,'We can handle things from here.  I thank you for your help, $N.$b$bI assume that when we next meet, it will be in battle.  Take care of yourself until then.  We''ll need all the help we can get.',0),
(27175,1,0,0,0,0,0,0,0,'Welcome, $c.  As you can see, our camp is a joint expedition between Argent Crusade members and Cenarion Circle druids, but we welcome all who wish to help heal the land.',0),
(27197,396,0,0,0,0,0,0,0,'Word has it that you helped those farmers arm themselves.  Well, now they''ve initiated the attack without my order!  They''ve forced my hand.$b$bThe battle has resumed.  This time, we fight the Forsaken... and I fight Koltira, my old brother of the Ebon Blade.',0),
(27198,1,0,0,0,0,0,0,0,'You fight well, $n.  I wish I had your ability... and your bravery.',0),
(27199,1,0,0,0,0,0,0,0,'Well done.  With them out of the way, I have no more excuses.$b$bSoon, I must battle Koltira, for honor and for Andorhal.',0),
(27201,1,0,0,0,0,0,0,0,'For every val''kyr you slay, you save dozens of our men... and prevent the Forsaken forces from growing.$b$bStill, they press on.  We may not win this battle after all.',0),
(27202,1,1,0,0,0,0,0,0,'You fought valiantly, but we''re getting nowhere.  Every body that falls just fuels their forces.',0),
(27204,1,0,0,0,0,0,0,0,'I watched your victory from below.  Well-fought, but ultimately, it was for naught.$b$bThe val''kyr and the Forsaken press on; soon, they will overtake us.  We have lost Andorhal.',0),
(27205,5,274,0,0,0,0,0,0,'Val''kyr?  Koltira brought val''kyr to this fight?  Has he gone mad?$b$bNo, this is not Koltira''s work.  This was Sylvanas.',0),
(27206,1,1,0,0,0,0,0,0,'Lost?  No... next, they''ll be coming for Chillwind, I suppose.  This was a major strategic blow to the Alliance''s plans for Lordaeron.$b$bVery well.  I will report the results of this battle to King Wrynn.  I don''t expect him to be happy.',0),
(28575,66,1,5,0,0,0,0,0,'Is this all the warchief can spare? Don''t worry, you''ll be put to good use.',0),
(28576,0,0,0,0,0,0,0,0,'There is much to be done here. Both of our enemies are relentless and would slaughter us without mercy the moment we sheathe our blades.',0),
(28749,396,0,0,0,0,0,0,0,'It''s about time you arrived, $c.',0),
(28750,396,0,0,0,0,0,0,0,'It''s about time you arrived, $c.',0);
